func (s *OrderServiceImpl) Process(ctx context.Context, params *ProcessOrderParams) (*entity.Order, error, []ParamError) {
    logger.Info("processing order")
    order, err := s.OrderRepo.ForID(params.GetID()).Get(ctx)
    if err != nil {
        logger.Error("repo error: " + err.Error())
        return nil, err, nil
    }
    if order == nil {
        return nil, nil, nil
    }
    order.Status = "processed"
    if err := s.OrderRepo.Update(ctx, order); err != nil {
        fmt.Println("update failed", err)
        return nil, err, nil
    }
    logger.Info("processed order " + fmt.Sprint(order.ID))
    return order, nil, nil
}
